//
// The 5GS NAS message tables (TS 24.501 clause 8), generated by tools/nasgen.py
// from spec/nas/24501 into the build tree. One IeDesc per row of a message
// table, the header octets included.

#pragma once

#include <cstddef>
#include <cstdint>
#include <span>

namespace ksim::nas {

enum class Epd : std::uint8_t { mm = 0x7E, sm = 0x2E };   // TS 24.501 9.2
enum class Direction : std::uint8_t { dl, ul, both };
enum class Presence : std::uint8_t { m, o, c };
enum class Format : std::uint8_t { v, lv, lv_e, t, tv, tlv, tlv_e };   // TS 24.007 11.2.1.1
enum class IeiKind : std::uint8_t { none, half, full };   // imperative part; type 1 (bits 8-5); octet

struct IeDesc {
    const char* name;       // the IE as the message table names it
    const char* type_name;  // its IE type (clause 9.11 and kin)
    const char* reference;  // that type's clause
    std::uint8_t iei;       // full IEI, or the type 1 IEI in the low four bits
    IeiKind iei_kind;
    Format format;
    std::uint16_t min_len;  // total octets with IEI and length; 0 and 0 for a half-octet V
    std::uint16_t max_len;  // 0xFFFF: no upper bound in the table ("n")
    Presence presence;

    bool half_octet() const noexcept { return format == Format::v && min_len == 0 && max_len == 0; }
};

struct MsgDesc {
    const char* key;      // the clause, e.g. "8.2.6"
    const char* name;     // e.g. "REGISTRATION REQUEST"
    Epd epd;
    std::uint8_t type;    // message type (TS 24.501 9.7)
    Direction direction;
    const IeDesc* ies;
    std::size_t ie_count;

    std::span<const IeDesc> table() const noexcept { return {ies, ie_count}; }
};

/// A container identifier of TS 24.008 10.5.6.3 in one direction.
struct EpcoDesc {
    std::uint16_t id;
    Direction direction;          // ul (MS to network) or dl
    std::uint8_t length_octets;   // the size of its length field: 1, or 2 (the NOTE to figure 10.5.136)
    const char* name;
};

namespace detail {
extern const MsgDesc kMessages[];
extern const std::size_t kMessageCount;
extern const EpcoDesc kEpco[];
extern const std::size_t kEpcoCount;
} // namespace detail

inline std::span<const EpcoDesc> epco_containers() noexcept {
    return {detail::kEpco, detail::kEpcoCount};
}

inline std::span<const MsgDesc> messages() noexcept {
    return {detail::kMessages, detail::kMessageCount};
}

} // namespace ksim::nas
